  // Generated by scripts/build-kpk.cjs: exact KPK wins, all other legal states draw.
  var KPK_DATA = '';

  var KPK_BITS = null;
  function probeKPK(pos) {
    var pawn = -1, owner = 0, b = pos.b;
    for (var s = 0; s < 128; s++) {
      if (s & 0x88) { s += 7; continue; }
      if (!b[s] || (b[s] & 7) === K) continue;
      if ((b[s] & 7) !== P || pawn >= 0) return null;
      pawn = s; owner = b[s] & BLACK;
    }
    if (pawn < 0) return null;
    if (!KPK_BITS) {
      KPK_BITS = new Uint8Array(24576);
      var alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/', bits = 0, n = 0, out = 0;
      for (var j = 0; j < KPK_DATA.length; j++) {
        bits = (bits << 6) | alphabet.indexOf(KPK_DATA[j]); n += 6;
        if (n >= 8) { n -= 8; KPK_BITS[out++] = (bits >> n) & 255; }
      }
    }
    var wk = pos.kingSq[owner >> 3], bk = pos.kingSq[(owner ^ BLACK) >> 3];
    // Map the pawn owner to White, then reflect files to a-d.
    var ps = ((pawn >> 4) * 8) + (pawn & 7), ws = ((wk >> 4) * 8) + (wk & 7), bs = ((bk >> 4) * 8) + (bk & 7);
    if (owner) { ps ^= 56; ws ^= 56; bs ^= 56; }
    if ((ps & 7) > 3) { ps ^= 7; ws ^= 7; bs ^= 7; }
    if ((ps >> 3) < 1 || (ps >> 3) > 6) return null;
    var index = ((((ps & 7) * 6 + (ps >> 3) - 1) * 64 + ws) * 64 + bs) * 2 + (pos.side === owner ? 0 : 1);
    return { win: !!(KPK_BITS[index >> 3] & (1 << (index & 7))), owner: owner };
  }

